74	const DOCUMENTS_META = 'documents-meta.json';
75	
76	export class DocumentService {
77	  private persistence: PersistenceService;
78	
79	  constructor(persistence: PersistenceService) {
80	    this.persistence = persistence;
81	  }
82	
83	  /** List all imported documents. */
84	  listDocuments(): Document[] {
85	    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
86	    return docs ?? [];
87	  }
88	
89	  /** Import a file from the given path. */
90	  importDocument(filePath: string): Document {
91	    if (!fs.existsSync(filePath)) {
92	      throw new Error(`File not found: ${filePath}`);
93	    }
94	
95	    const filename = path.basename(filePath);
96	    const content = fs.readFileSync(filePath, 'utf-8');
97	    const stats = fs.statSync(filePath);
98	
99	    const doc: Document = {
100	      id: uuidv4(),
101	      title: filename.replace(/\.[^.]+$/, ''),
102	      filename,
103	      importedAt: new Date().toISOString(),
104	      size: stats.size,
105	      status: 'imported',
106	    };
107	
108	    // Copy file to data directory
109	    this.persistence.copyFileToDocuments(filePath, filename);
110	
111	    // Store content for indexing
112	    this.persistence.writeText(`content/${doc.id}.txt`, content);
113	
114	    // Update metadata
115	    const docs = this.listDocuments();
116	    docs.push(doc);
117	    this.persistence.writeJson(DOCUMENTS_META, docs);
118	
119	    return doc;
120	  }
121	
122	  /** Get a single document by ID. */
123	  getDocument(id: string): Document | null {
124	    const docs = this.listDocuments();
125	    return docs.find(d => d.id === id) ?? null;
126	  }
127	
128	  /** Get the text content of a document. */
129	  getDocumentContent(id: string): string | null {
130	    return this.persistence.readText(`content/${id}.txt`);
131	  }
132	
133	  /** Update a document's metadata. */
134	  updateDocument(id: string, updates: Partial<Document>): Document | null {
135	    const docs = this.listDocuments();
136	    const index = docs.findIndex(d => d.id === id);
137	    if (index === -1) return null;
138	
139	    docs[index] = { ...docs[index], ...updates };
140	    this.persistence.writeJson(DOCUMENTS_META, docs);
141	    return docs[index];
142	  }
143	
144	  /** Delete a document by ID. */
145	  deleteDocument(id: string): boolean {
146	    const docs = this.listDocuments();
147	    const doc = docs.find(d => d.id === id);
148	    if (!doc) return false;
149	
150	    this.persistence.deleteFromDocuments(doc.filename);
151	
152	    const updated = docs.filter(d => d.id !== id);
153	    this.persistence.writeJson(DOCUMENTS_META, updated);
154	    return true;
155	  }
156	}
