161	export class PersistenceService {
162	  private dataDir: string;
163	  private documentsDir: string;
164	  private indexDir: string;
165	
166	  constructor(dataDir: string) {
167	    this.dataDir = dataDir;
168	    this.documentsDir = path.join(dataDir, 'documents');
169	    this.indexDir = path.join(dataDir, 'index');
170	    this.ensureDirectories();
171	  }
172	
173	  private ensureDirectories() {
174	    fs.mkdirSync(this.dataDir, { recursive: true });
175	    fs.mkdirSync(this.documentsDir, { recursive: true });
176	    fs.mkdirSync(this.indexDir, { recursive: true });
177	  }
178	
179	  /** Read a JSON file, returning null if it doesn't exist. */
180	  readJson<T>(relativePath: string): T | null {
181	    const fullPath = path.join(this.dataDir, relativePath);
182	    if (!fs.existsSync(fullPath)) return null;
183	    return JSON.parse(fs.readFileSync(fullPath, 'utf-8'));
184	  }
185	
186	  /** Write a JSON file atomically. */
187	  writeJson<T>(relativePath: string, data: T): void {
188	    const fullPath = path.join(this.dataDir, relativePath);
189	    const dir = path.dirname(fullPath);
190	    fs.mkdirSync(dir, { recursive: true });
191	    fs.writeFileSync(fullPath, JSON.stringify(data, null, 2), 'utf-8');
192	  }
193	
194	  /** Read a text file. */
195	  readText(relativePath: string): string | null {
196	    const fullPath = path.join(this.dataDir, relativePath);
197	    if (!fs.existsSync(fullPath)) return null;
198	    return fs.readFileSync(fullPath, 'utf-8');
199	  }
200	
201	  /** Write a text file. */
202	  writeText(relativePath: string, content: string): void {
203	    const fullPath = path.join(this.dataDir, relativePath);
204	    const dir = path.dirname(fullPath);
205	    fs.mkdirSync(dir, { recursive: true });
206	    fs.writeFileSync(fullPath, content, 'utf-8');
207	  }
208	
209	  /** Copy a file into the documents directory. */
210	  copyFileToDocuments(sourcePath: string, filename: string): string {
211	    const destPath = path.join(this.documentsDir, filename);
212	    fs.mkdirSync(this.documentsDir, { recursive: true });
213	    fs.copyFileSync(sourcePath, destPath);
214	    return destPath;
215	  }
216	
217	  /** Delete a file from the documents directory. */
218	  deleteFromDocuments(filename: string): void {
219	    const filePath = path.join(this.documentsDir, filename);
220	    if (fs.existsSync(filePath)) {
221	      fs.unlinkSync(filePath);
222	    }
223	  }
