      throw new Error('No file path provided');
    }
    if (!path.isAbsolute(filePath)) {
      throw new Error('File path must be absolute');
    }

    const filename = path.basename(filePath);
    const ext = path.extname(filename).toLowerCase();
    if (!(SUPPORTED_EXTENSIONS as readonly string[]).includes(ext)) {
      throw new Error(`Unsupported file type "${ext || '(none)'}". Supported: ${SUPPORTED_EXTENSIONS.join(', ')}`);
    }

    let stats: fs.Stats;
    try {
      stats = fs.statSync(filePath);
    } catch {
      throw new Error('File not found');
    }
    if (!stats.isFile()) {
      throw new Error('Not a regular file');
    }
    if (stats.size > MAX_IMPORT_FILE_SIZE) {
      const mb = (stats.size / (1024 * 1024)).toFixed(1);
      throw new Error(`File is too large (${mb} MB). Maximum is ${MAX_IMPORT_FILE_SIZE / (1024 * 1024)} MB`);
    }

    const content = decodeText(fs.readFileSync(filePath));

    const id = uuidv4();
    const doc: Document = {
      id,
      title: deriveTitle(filename),
      filename,
      importedAt: new Date().toISOString(),
      size: stats.size,
      status: 'imported',
    };

    // Store the original under an ID-based name so two files with the same
    // name (from different folders) never overwrite each other.
    const storedName = storedFilename(doc);
    const contentPath = `content/${id}.txt`;
    try {
      this.persistence.copyFileToDocuments(filePath, storedName);
      this.persistence.writeText(contentPath, content);

      const docs = this.listDocuments();
      docs.push(doc);
      this.persistence.writeJson(DOCUMENTS_META, docs);
    } catch (err) {
      // Roll back partial writes so we don't leave orphaned files behind.
      this.persistence.deleteFromDocuments(storedName);
      this.persistence.deleteFile(contentPath);
      throw err;
    }

    return doc;
  }

