import { useState, type DragEvent } from 'react';
import { ImportResult, MAX_IMPORT_FILE_SIZE, SUPPORTED_EXTENSIONS } from '../../shared/types';

interface Props {
  /** Called after an import attempt that imported at least one document. */
  onImported: (result: ImportResult) => void;
}

const MAX_MB = MAX_IMPORT_FILE_SIZE / (1024 * 1024);

export function ImportPanel({ onImported }: Props) {
  const [busy, setBusy] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [result, setResult] = useState<ImportResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const run = async (action: () => Promise<ImportResult>) => {
    if (busy) return;
    setBusy(true);
    setError(null);
    try {
      const res = await action();
      if (res.canceled) return;
      setResult(res);
      if (res.imported.length > 0) onImported(res);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const handlePick = () => run(() => window.knowledgeBase.documents.importWithDialog());

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(false);
    const files = Array.from(e.dataTransfer.files);
    if (files.length === 0) return;
    const paths = files
      .map(f => window.knowledgeBase.documents.getPathForFile(f))
      .filter(p => p.length > 0);
    if (paths.length === 0) {
      setError('Dropped items are not files on disk.');
      return;
    }
    void run(() => window.knowledgeBase.documents.import(paths));
  };

  return (
    <div>
      <div
        data-testid="import-dropzone"
        onDragOver={e => {
          e.preventDefault();
          e.dataTransfer.dropEffect = 'copy';
          if (!dragOver) setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        style={{
          padding: '28px 20px',
          background: dragOver ? '#1f2a52' : '#16213e',
          borderRadius: '6px',
          border: `1px dashed ${dragOver ? '#8a6cc4' : '#0f3460'}`,
          textAlign: 'center',
          color: '#888',
          transition: 'background 0.15s, border-color 0.15s',
        }}
      >
        <div style={{ fontSize: '14px', marginBottom: '8px', color: '#c0c0e0' }}>Import Documents</div>
        <div style={{ fontSize: '12px', marginBottom: '14px' }}>
          Choose files or drag them here.
          <br />
          Supported: {SUPPORTED_EXTENSIONS.join(', ')} (up to {MAX_MB} MB each)
        </div>
        <button
          onClick={handlePick}
          disabled={busy}
          style={{
            padding: '6px 16px',
            background: busy ? '#3a2a5c' : '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '4px',
            cursor: busy ? 'default' : 'pointer',
            fontSize: '13px',
          }}
        >
          {busy ? 'Importing…' : 'Choose Files…'}
        </button>
      </div>

      {error && (
        <div role="alert" style={{ marginTop: '12px', fontSize: '12px', color: '#e07a7a' }}>
          Import failed: {error}
        </div>
      )}

      {result && (
        <div data-testid="import-result" style={{ marginTop: '12px', fontSize: '12px' }}>
          {result.imported.length > 0 && (
            <div style={{ color: '#7ac77a' }}>
              Imported {result.imported.length} document{result.imported.length === 1 ? '' : 's'}:{' '}
              {result.imported.map(d => d.filename).join(', ')}
            </div>
          )}
          {result.failed.length > 0 && (
            <div role="alert" style={{ marginTop: '6px', color: '#e07a7a' }}>
              {result.failed.length} file{result.failed.length === 1 ? '' : 's'} could not be imported:
              <ul style={{ margin: '4px 0 0 18px' }}>
                {result.failed.map((f, i) => (
                  <li key={i}>
                    <strong>{f.filename}</strong>: {f.message}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

