import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { MAX_IMPORT_FILE_SIZE } from '../shared/types';
import { DocumentService } from './document-service';
import { PersistenceService } from './persistence-service';

const SAMPLES = path.resolve(__dirname, '../../data/sample-documents');

describe('DocumentService import', () => {
  let tmp: string;
  let dataDir: string;
  let srcDir: string;
  let service: DocumentService;

  beforeEach(() => {
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-import-'));
    dataDir = path.join(tmp, 'data');
    srcDir = path.join(tmp, 'src');
    fs.mkdirSync(srcDir);
    service = new DocumentService(new PersistenceService(dataDir));
  });

  afterEach(() => {
    fs.rmSync(tmp, { recursive: true, force: true });
  });

  const writeSource = (name: string, content: string | Buffer, dir = srcDir) => {
    fs.mkdirSync(dir, { recursive: true });
    const p = path.join(dir, name);
    fs.writeFileSync(p, content);
    return p;
  };

  it('imports the sample .md and .txt documents', () => {
    const files = fs.readdirSync(SAMPLES).map(f => path.join(SAMPLES, f));
    const result = service.importDocuments(files);

    expect(result.failed).toEqual([]);
    expect(result.imported).toHaveLength(files.length);
    expect(service.listDocuments().map(d => d.filename).sort()).toEqual(
      fs.readdirSync(SAMPLES).sort(),
    );
    for (const doc of result.imported) {
      const original = fs.readFileSync(path.join(SAMPLES, doc.filename), 'utf-8');
      expect(service.getDocumentContent(doc.id)).toBe(original);
      expect(doc.size).toBe(fs.statSync(path.join(SAMPLES, doc.filename)).size);
      expect(doc.status).toBe('imported');
    }
  });

  it('derives title from filename and records metadata', () => {
    const doc = service.importDocument(writeSource('Project Notes.MD', '# Hi\n'));
    expect(doc.title).toBe('Project Notes');
    expect(doc.filename).toBe('Project Notes.MD');
    expect(Number.isNaN(Date.parse(doc.importedAt))).toBe(false);
    expect(fs.existsSync(path.join(dataDir, 'documents', `${doc.id}.md`))).toBe(true);
  });

  it('keeps both files when two have the same name', () => {
    const a = service.importDocument(writeSource('notes.txt', 'first', path.join(srcDir, 'a')));
    const b = service.importDocument(writeSource('notes.txt', 'second', path.join(srcDir, 'b')));

    expect(service.getDocumentContent(a.id)).toBe('first');
    expect(service.getDocumentContent(b.id)).toBe('second');
    expect(fs.readFileSync(path.join(dataDir, 'documents', `${a.id}.txt`), 'utf-8')).toBe('first');
    expect(fs.readFileSync(path.join(dataDir, 'documents', `${b.id}.txt`), 'utf-8')).toBe('second');

    // Deleting one must not remove the other's stored copy.
    service.deleteDocument(a.id);
    expect(fs.existsSync(path.join(dataDir, 'documents', `${b.id}.txt`))).toBe(true);
  });

  it('strips a UTF-8 BOM and preserves non-ASCII text', () => {
    const doc = service.importDocument(writeSource('bom.txt', '﻿Café — ñandú ✓'));
    expect(service.getDocumentContent(doc.id)).toBe('Café — ñandú ✓');
  });

  it('accepts an empty file', () => {
    const doc = service.importDocument(writeSource('empty.md', ''));
    expect(doc.size).toBe(0);
    expect(service.getDocumentContent(doc.id)).toBe('');
  });

  it.each([
    ['unsupported extension', () => writeSource('photo.png', 'x'), /Unsupported file type ".png"/],
    ['no extension', () => writeSource('README', 'x'), /Unsupported file type "\(none\)"/],
    ['missing file', () => path.join(srcDir, 'nope.txt'), /File not found/],
    ['directory', () => { const d = path.join(srcDir, 'dir.md'); fs.mkdirSync(d); return d; }, /Not a regular file/],
    ['binary content', () => writeSource('bin.txt', Buffer.from([0x48, 0x00, 0x49])), /binary/],
    ['invalid UTF-8', () => writeSource('latin1.txt', Buffer.from([0x63, 0x61, 0x66, 0xe9])), /not valid UTF-8/],
    ['relative path', () => 'relative/notes.txt', /must be absolute/],
  ])('rejects %s without writing anything', (_label, makePath, message) => {
    expect(() => service.importDocument(makePath())).toThrow(message);
    expect(service.listDocuments()).toEqual([]);
    expect(fs.readdirSync(path.join(dataDir, 'documents'))).toEqual([]);
    expect(fs.existsSync(path.join(dataDir, 'content'))).toBe(false);
  });

  it('rejects files over the size limit', () => {
    const p = path.join(srcDir, 'big.txt');
    fs.writeFileSync(p, '');
    fs.truncateSync(p, MAX_IMPORT_FILE_SIZE + 1);
    expect(() => service.importDocument(p)).toThrow(/too large/);
    expect(service.listDocuments()).toEqual([]);
  });

  it('accepts a file exactly at the size limit', () => {
    const p = writeSource('limit.txt', Buffer.alloc(MAX_IMPORT_FILE_SIZE, 'a'));
    expect(service.importDocument(p).size).toBe(MAX_IMPORT_FILE_SIZE);
  });

  it('imports valid files and reports invalid ones in the same batch', () => {
    const result = service.importDocuments([
      writeSource('good.md', '# ok'),
      writeSource('bad.pdf', 'x'),
      path.join(srcDir, 'missing.txt'),
      writeSource('also-good.txt', 'ok'),
    ]);
    expect(result.imported.map(d => d.filename)).toEqual(['good.md', 'also-good.txt']);
    expect(result.failed.map(f => f.filename)).toEqual(['bad.pdf', 'missing.txt']);
    expect(result.canceled).toBe(false);
    expect(service.listDocuments()).toHaveLength(2);
  });
});

